//! Applying a complete desktop profile.
//!
//! A profile is applied as one theme transaction plus the files it owns: the
//! Hyprland layout snippet is part of that transaction, so `restore` and
//! `rollback` treat it like any other generated file. Asset settings and the
//! wallpaper are recorded after the transaction succeeded.

use std::fs;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use config_manager::{ConfigError, install_content};
use desktop_assets::{
    AssetError, AssetSettings, WallpaperLibrary, WallpaperState, detect_tool, set_wallpaper,
    write_settings,
};
use desktop_profiles::{Profile, ProfileLayout};

use crate::LoadedTheme;
use crate::integrations;
use crate::transaction::{ApplyError, apply_theme_with_extra};

/// Hyprland snippet generated from the profile layout, relative to the root.
pub const LAYOUT_RELATIVE_PATH: &str = "hyprland/layout.conf";

#[derive(Debug)]
pub enum ProfileApplyError {
    Profile(String),
    Wallpaper(String),
    Apply(ApplyError),
    Asset(AssetError),
    State(ConfigError),
}

impl std::fmt::Display for ProfileApplyError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Profile(message) => write!(f, "{message}"),
            Self::Wallpaper(message) => write!(f, "{message}"),
            Self::Apply(error) => write!(f, "{error}"),
            Self::Asset(error) => write!(f, "{error}"),
            Self::State(error) => write!(f, "{error}"),
        }
    }
}

impl std::error::Error for ProfileApplyError {}

impl From<ApplyError> for ProfileApplyError {
    fn from(error: ApplyError) -> Self {
        Self::Apply(error)
    }
}

impl From<AssetError> for ProfileApplyError {
    fn from(error: AssetError) -> Self {
        Self::Asset(error)
    }
}

impl From<ConfigError> for ProfileApplyError {
    fn from(error: ConfigError) -> Self {
        Self::State(error)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProfileApplyOptions {
    /// Switch the wallpaper through a detected daemon.
    pub set_wallpaper: bool,
    /// Reload detected applications after the transaction.
    pub reload: bool,
}

impl Default for ProfileApplyOptions {
    fn default() -> Self {
        Self {
            set_wallpaper: true,
            reload: false,
        }
    }
}

#[derive(Debug, Clone)]
pub struct ProfileReport {
    pub profile_id: String,
    pub theme_id: String,
    pub installed_files: Vec<String>,
    pub wallpaper: Option<PathBuf>,
    pub wallpaper_commands: Vec<String>,
    pub layout_file: String,
    pub asset_snippet: PathBuf,
    pub reloaded: Vec<String>,
    /// Non-fatal problems, for example a missing wallpaper daemon.
    pub warnings: Vec<String>,
}

/// Renders the Hyprland layout snippet for a profile.
pub fn render_layout(layout: &ProfileLayout) -> String {
    let mut output = String::new();

    output.push_str("# Generated by My Linux Theme Engine. Do not edit manually.\n");
    output.push_str("# Source it from ~/.config/hypr/hyprland.conf:\n");
    output.push_str("#   source = ~/.config/hypr/layout.conf\n\n");
    output.push_str("general {\n");
    output.push_str(&format!("    gaps_in = {}\n", layout.gaps_in));
    output.push_str(&format!("    gaps_out = {}\n", layout.gaps_out));
    output.push_str(&format!("    border_size = {}\n", layout.border_size));
    output.push_str("}\n\n");
    output.push_str("decoration {\n");
    output.push_str(&format!("    rounding = {}\n", layout.rounding));
    output.push_str(&format!(
        "    active_opacity = {:.2}\n",
        layout.active_opacity
    ));
    output.push_str(&format!(
        "    inactive_opacity = {:.2}\n",
        layout.inactive_opacity
    ));
    output.push_str("\n    blur {\n");
    output.push_str(&format!("        enabled = {}\n", layout.blur));
    output.push_str("    }\n}\n");

    output
}

fn resolve_wallpaper(query: &str) -> Result<PathBuf, ProfileApplyError> {
    let path = PathBuf::from(query);

    if path.is_file() {
        return Ok(path);
    }

    WallpaperLibrary::from_environment()
        .find(query)
        .map(|wallpaper| wallpaper.path)
        .ok_or_else(|| {
            ProfileApplyError::Wallpaper(format!(
                "Wallpaper `{query}` was not found; add it to the wallpaper library or use an absolute path"
            ))
        })
}

fn profile_history_file(root: &Path) -> PathBuf {
    root.join("state").join("profile-history.log")
}

fn append_history(root: &Path, profile: &str, files: &[String]) -> Result<(), ConfigError> {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0);

    let mut content = format!("{timestamp}\tapply\t{profile}\t{}\n", files.join(","));

    if let Ok(existing) = fs::read_to_string(profile_history_file(root)) {
        content = format!("{existing}{content}");
    }

    install_content(content.as_bytes(), profile_history_file(root))
}

/// Applies a profile: integrations, layout, assets and wallpaper.
///
/// Everything that can be validated is checked before the first file is
/// written, so a profile with a missing wallpaper or theme reference leaves the
/// installation untouched.
pub fn apply_profile(
    root: impl AsRef<Path>,
    profile: &Profile,
    theme: &LoadedTheme,
    options: &ProfileApplyOptions,
) -> Result<ProfileReport, ProfileApplyError> {
    apply_profile_with_extensions(root, profile, theme, options, &[])
}

/// Applies a profile plus extra generated files (enabled extensions), all in the
/// same transaction as the integrations and layout snippet.
pub fn apply_profile_with_extensions(
    root: impl AsRef<Path>,
    profile: &Profile,
    theme: &LoadedTheme,
    options: &ProfileApplyOptions,
    extra: &[(String, String)],
) -> Result<ProfileReport, ProfileApplyError> {
    let root = root.as_ref();

    match apply_profile_transaction(root, profile, theme, options, extra) {
        Ok(report) => {
            let _ = crate::log::append_event(
                root,
                crate::log::Level::Info,
                "profile",
                &format!(
                    "profile={} theme={} files={}",
                    report.profile_id,
                    report.theme_id,
                    report.installed_files.len()
                ),
            );

            Ok(report)
        }
        Err(error) => {
            let _ = crate::log::append_event(
                root,
                crate::log::Level::Error,
                "profile-failed",
                &format!("profile={} error={error}", profile.metadata.id),
            );

            Err(error)
        }
    }
}

fn apply_profile_transaction(
    root: &Path,
    profile: &Profile,
    theme: &LoadedTheme,
    options: &ProfileApplyOptions,
    extensions: &[(String, String)],
) -> Result<ProfileReport, ProfileApplyError> {
    profile
        .validate()
        .map_err(|error| ProfileApplyError::Profile(error.to_string()))?;

    let wallpaper = match profile.metadata.wallpaper.as_deref() {
        Some(query) => Some(resolve_wallpaper(query)?),
        None => None,
    };

    let selected =
        integrations::select(&profile.metadata.integrations).map_err(ProfileApplyError::Profile)?;

    let mut extra = vec![(
        LAYOUT_RELATIVE_PATH.to_string(),
        render_layout(&profile.layout),
    )];

    extra.extend(extensions.iter().cloned());

    // Record the wallpaper before the transaction so the lock screen generated
    // inside it already points at the profile's wallpaper.
    if let Some(path) = &wallpaper {
        WallpaperState::new(root).set(path, "profile")?;
    }

    let report = apply_theme_with_extra(root, theme, &selected, &extra)?;

    let assets = AssetSettings {
        font: profile.assets.font.clone(),
        font_size: profile.assets.font_size,
        icon_theme: profile.assets.icon_theme.clone(),
        cursor_theme: profile.assets.cursor_theme.clone(),
        cursor_size: profile.assets.cursor_size,
    };

    write_settings(root, &assets)?;

    let mut warnings = Vec::new();
    let mut wallpaper_commands = Vec::new();

    if let Some(path) = &wallpaper
        && options.set_wallpaper
    {
        match detect_tool() {
            Some(tool) => match set_wallpaper(tool, path) {
                Ok(commands) => wallpaper_commands = commands,
                Err(error) => warnings.push(error.to_string()),
            },
            None => warnings
                .push("No wallpaper daemon detected; the wallpaper was recorded only".to_string()),
        }
    }

    let mut reloaded = Vec::new();

    if options.reload {
        for integration in &selected {
            match integrations::reload(*integration) {
                Ok(commands) => reloaded.extend(commands),
                Err(error) => {
                    warnings.push(format!("{} did not reload: {error}", integration.id()));
                }
            }
        }
    }

    crate::write_active_profile(root, &profile.metadata.id)?;
    append_history(root, &profile.metadata.id, &report.installed_files)?;

    Ok(ProfileReport {
        profile_id: profile.metadata.id.clone(),
        theme_id: theme.metadata.id.clone(),
        installed_files: report.installed_files,
        wallpaper,
        wallpaper_commands,
        layout_file: LAYOUT_RELATIVE_PATH.to_string(),
        asset_snippet: desktop_assets::hyprland_assets_file(root),
        reloaded,
        warnings,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn test_dir(name: &str) -> PathBuf {
        let dir =
            std::env::temp_dir().join(format!("my-linux-profile-{}-{}", name, std::process::id()));

        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();

        dir
    }

    fn theme(name: &str) -> LoadedTheme {
        crate::load_desktop_theme("../../themes", name).expect("theme should load")
    }

    #[test]
    fn lock_screen_uses_the_profile_wallpaper() {
        let dir = test_dir("wallpaper");
        let image = dir.join("wallpaper.png");

        fs::write(&image, b"not really a png").unwrap();

        let mut profile = Profile::new("lock", "Lock", "cyberpunk").unwrap();

        profile.metadata.integrations = vec!["hyprlock".to_string()];
        profile.metadata.wallpaper = Some(image.display().to_string());
        profile.validate().unwrap();

        apply_profile_with_extensions(
            &dir,
            &profile,
            &theme("cyberpunk"),
            &ProfileApplyOptions {
                set_wallpaper: false,
                reload: false,
            },
            &[],
        )
        .unwrap();

        let conf = fs::read_to_string(dir.join("hyprlock/hyprlock.conf")).unwrap();

        assert!(conf.contains(&format!("path = {}", image.display())));
        assert_eq!(
            WallpaperState::new(&dir).current().as_deref(),
            Some(image.as_path())
        );
    }

    #[test]
    fn applies_enabled_extensions_with_a_profile() {
        let dir = test_dir("extensions");
        let mut profile = Profile::new("dev-ext", "Developer", "cyberpunk").unwrap();

        profile.metadata.integrations = vec!["waybar".to_string()];
        profile.validate().unwrap();

        let extra = vec![(
            "extra/style.conf".to_string(),
            "accent = #FF235A\n".to_string(),
        )];
        let report = apply_profile_with_extensions(
            &dir,
            &profile,
            &theme("cyberpunk"),
            &ProfileApplyOptions {
                set_wallpaper: false,
                reload: false,
            },
            &extra,
        )
        .unwrap();

        assert!(dir.join("extra/style.conf").is_file());
        assert!(
            report
                .installed_files
                .iter()
                .any(|file| file == "extra/style.conf")
        );

        crate::restore_theme(&dir).unwrap();

        assert!(!dir.join("extra/style.conf").exists());

        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn applies_a_profile_as_one_transaction() {
        let dir = test_dir("apply");
        let wallpaper = dir.join("wall.png");

        fs::write(&wallpaper, "pixels").unwrap();

        let mut profile = Profile::new("dev", "Developer", "cyberpunk").unwrap();

        profile.metadata.wallpaper = Some(wallpaper.display().to_string());
        profile.metadata.integrations = vec!["waybar".to_string(), "rofi".to_string()];
        profile.assets.font = Some("Inter".to_string());
        profile.assets.cursor_size = 28;
        profile.layout.rounding = 3;
        profile.validate().unwrap();

        let report = apply_profile(
            &dir,
            &profile,
            &theme("cyberpunk"),
            &ProfileApplyOptions {
                set_wallpaper: false,
                reload: false,
            },
        )
        .unwrap();

        assert_eq!(report.profile_id, "dev");
        assert_eq!(report.theme_id, "cyberpunk");
        assert_eq!(report.installed_files.len(), 3);
        assert_eq!(report.wallpaper.as_deref(), Some(wallpaper.as_path()));
        assert!(dir.join("waybar.css").is_file());
        assert!(dir.join("rofi/theme.rasi").is_file());
        assert!(!dir.join("kitty/my-linux.conf").exists());

        let layout = fs::read_to_string(dir.join(LAYOUT_RELATIVE_PATH)).unwrap();
        assert!(layout.contains("rounding = 3"));
        assert!(layout.contains("gaps_in = 5"));

        let assets = fs::read_to_string(dir.join("state/assets.conf")).unwrap();
        assert!(assets.contains("font=Inter"));
        assert!(assets.contains("cursor_size=28"));

        assert_eq!(
            fs::read_to_string(dir.join("state/wallpaper"))
                .unwrap()
                .trim(),
            wallpaper.display().to_string()
        );
        assert_eq!(crate::read_active_profile(&dir).as_deref(), Some("dev"));

        // The layout snippet belongs to the transaction, so restoring removes it.
        crate::restore_theme(&dir).unwrap();

        assert!(!dir.join(LAYOUT_RELATIVE_PATH).exists());
        assert!(!dir.join("waybar.css").exists());
        assert_eq!(crate::read_active_profile(&dir), None);

        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn a_missing_wallpaper_leaves_the_installation_untouched() {
        let dir = test_dir("missing-wallpaper");

        let mut profile = Profile::new("dev", "Developer", "nature").unwrap();

        profile.metadata.wallpaper = Some("/definitely/missing/wallpaper.png".to_string());

        let result = apply_profile(
            &dir,
            &profile,
            &theme("nature"),
            &ProfileApplyOptions {
                set_wallpaper: false,
                reload: false,
            },
        );

        assert!(matches!(result, Err(ProfileApplyError::Wallpaper(_))));
        assert!(!dir.join("waybar.css").exists());
        assert_eq!(crate::read_active_profile(&dir), None);

        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn switching_profiles_records_the_previous_one() {
        let dir = test_dir("switch");

        let first = Profile::new("first", "First", "cyberpunk").unwrap();
        let second = Profile::new("second", "Second", "nature").unwrap();

        apply_profile(
            &dir,
            &first,
            &theme("cyberpunk"),
            &ProfileApplyOptions::default(),
        )
        .unwrap();
        apply_profile(
            &dir,
            &second,
            &theme("nature"),
            &ProfileApplyOptions::default(),
        )
        .unwrap();

        assert_eq!(crate::read_active_profile(&dir).as_deref(), Some("second"));
        assert_eq!(crate::read_previous_profile(&dir).as_deref(), Some("first"));
        assert!(
            fs::read_to_string(dir.join("waybar.css"))
                .unwrap()
                .contains("#6EBE5A")
        );

        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn renders_the_layout_snippet() {
        let layout = ProfileLayout {
            gaps_in: 3,
            gaps_out: 9,
            border_size: 1,
            rounding: 7,
            active_opacity: 1.0,
            inactive_opacity: 0.9,
            blur: false,
        };

        let snippet = render_layout(&layout);

        assert!(snippet.contains("gaps_in = 3"));
        assert!(snippet.contains("gaps_out = 9"));
        assert!(snippet.contains("rounding = 7"));
        assert!(snippet.contains("inactive_opacity = 0.90"));
        assert!(snippet.contains("enabled = false"));
    }
}
